import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"取指与译码带宽","description":"","frontmatter":{"title":"取指与译码带宽","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fetch-decode-width.md","filePath":"cs/fetch-decode-width.md","lastUpdated":1789023840000}'),p={name:"cs/fetch-decode-width.md"};function E(A,a,B,_,u,m){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="取指与译码带宽" tabindex="-1">取指与译码带宽 <a class="header-anchor" href="#取指与译码带宽" aria-label="Permalink to &quot;取指与译码带宽&quot;">​</a></h1><div class="epigraph"><p>窗口再宽，每拍从 I-cache 送进译码器的字节数不够，发射队列也会饿死；变长 ISA 还让「一条」的边界本身就是关键路径。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Palacharla 等对前端复杂度的讨论 整理</footer></div><p><a href="/cs/value-prediction">上一课</a> 在后端用猜测填窗口。后端再能猜，指令还是要从 IF 进来。<a href="/cs/superscalar-issue">超标量发射</a> 已经要求每拍 \\(W\\) 条；乱序核的 \\(W\\) 更大，且分支之后的取指块可能不对齐。本课不重讲值表。缺口是<strong>前端带宽：对齐、预译码、跨行、以及变长指令的扫描。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RISC-V 定长 32 位（压缩 16 位另计）时，取 \\(W\\) 条近似取 \\(4W\\) 字节并对齐。x86 指令 1–15 字节，下一条起点依赖本条长度，扫描是串行进位链。I-cache 行边界、BTB 提供的起始 PC、预测块里的多条分支，都会让「这一拍的 \\(W\\) 条」凑不齐。缺口不是再加一个 ALU 口，而是<strong>让译码宽度配得上发射宽度</strong>。</p><p><span class="marginnote">前端停顿在 PMU 里常表现为 fetch starved：IQ 空、后端闲。与后端 replay 不同，这时预测器再准也没用，因为指令根本没进窗口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取指块：按 BTB/预测给出起始 PC，从 I-cache（可多 bank）读一行或两行，预译码位标出指令边界与是否分支。译码宽度 \\(D\\) 条送入重命名；多余的留在指令缓冲。跨行取指：一行末尾不够 \\(D\\) 条则同时读下一行，或下一拍再取。</p>',8)),(e(),n(h,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20IC%5B%22I-cache%20%E8%A1%8C%22%5D%20--%3E%20PRED%5B%22%E9%A2%84%E8%AF%91%E7%A0%81%E8%BE%B9%E7%95%8C%22%5D%0A%20%20BTB%5B%22BTB%20%2F%20%E9%A2%84%E6%B5%8B%E5%9D%97%22%5D%20--%3E%20PC0%5B%22%E5%9D%97%E8%B5%B7%E5%A7%8B%20PC%22%5D%0A%20%20PC0%20--%3E%20IC%0A%20%20PRED%20--%3E%20DEC%5B%22%E8%AF%91%E7%A0%81%20D%20%E6%9D%A1%22%5D%0A%20%20DEC%20--%3E%20REN%5B%22%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A%20%20DEC%20--%3E%20Q%5B%22%E6%8C%87%E4%BB%A4%E7%BC%93%E5%86%B2%E5%89%A9%E4%BD%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>压缩指令（RISC-V C、x86）让边界表更密。宏指令若要拆成微操作，译码带宽要以 uop 计，那是后课 uop cache 的动机。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/cpi-amdahl">CPI</a> 的理想项变成 \\(\\max(1/D, 1/W_{\\text{issue}}, \\ldots)\\) 的前端截断。分支密度高则每拍有效 \\(D\\) 下降：块在第一条预测分支处截断。这就是为何 BTB 与 gshare 不只影响损失拍，还影响<strong>取指打包</strong>。</p><p>功耗：每拍解 x86 边界的长度译码器是热点，推动后课把热循环的 uop 缓存起来，绕过长度扫描。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 uop cache 的命中路径，下一课才绕过译码器。也不把跟踪缓存（Rotenberg）当主干实现，只承认「把连续执行痕迹存起来」是同一类前端捷径。循环流缓冲是再下一课。</p><p>后课默认：前端有明确的每拍指令/字节上限；变长 ISA 的上限更脆。热路径若能跳过译码，带宽可以再挖一层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>取指/译码宽度是窗口的供给；变长 ISA 让供给更贵。</li><li>预测块截断会让有效宽度低于名义 \\(D\\)。</li><li>把热 uop 缓存起来绕过译码器，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Palacharla, Jouppi, Smith, <em>ISCA</em>, 1997。</li></ul>',9))])}const C=s(p,[["render",E]]);export{f as __pageData,C as default};
